// Manifest-based patcher. Has no Electron imports so it can be tested with plain Node.
//
// Manifest format (generated by tools/make-manifest.mjs):
// {
//   "version": "2026.10.13-1",
//   "compression": "gzip" | "none",
//   "layout": "sha256",                     // blobs live at files/<sha[0:2]>/<sha>[.gz]
//   "baseUrl": "https://cdn.example.com/files/",   // optional; defaults to <manifest dir>/files/
//   "files":  [ { "path": "Ashita/ashita-cli.exe", "size": 123, "sha256": "...", "csize": 80 } ],
//   "delete": [ "Ashita/addons/oldaddon/oldaddon.lua" ]
// }

import { createHash } from 'node:crypto'
import { createReadStream, createWriteStream, existsSync } from 'node:fs'
import { mkdir, readFile, rename, rm, stat, statfs, writeFile } from 'node:fs/promises'
import { dirname, isAbsolute, join, normalize, parse, sep } from 'node:path'
import { Readable, Transform, type Writable } from 'node:stream'
import { pipeline } from 'node:stream/promises'
import type { ReadableStream as WebReadableStream } from 'node:stream/web'
import { createGunzip } from 'node:zlib'
import type { PatchProgress, UpdateCheck } from '../shared/types'

export interface ManifestFile {
  path: string
  size: number
  sha256: string
  csize?: number
}

export interface Manifest {
  version: string
  compression?: 'gzip' | 'none'
  layout?: 'sha256'
  baseUrl?: string
  files: ManifestFile[]
  delete?: string[]
}

interface StateEntry {
  size: number
  mtimeMs: number
  sha256: string
}

interface LocalState {
  version?: string
  files: Record<string, StateEntry>
}

export interface PatchOptions {
  /** Ignore the cached hashes and re-hash every file on disk. */
  verify?: boolean
  signal?: AbortSignal
  concurrency?: number
}

const STATE_FILE = '.launcher-state.json'
/** Keep this much free space beyond what the update itself needs. */
const DISK_MARGIN = 512 * 1024 * 1024
const PROGRESS_INTERVAL_MS = 120

export class CancelledError extends Error {
  constructor() {
    super('Update cancelled.')
  }
}

/** Resolve a manifest path inside installDir, refusing anything that escapes it. */
export function safeJoin(root: string, rel: string): string {
  const clean = normalize(rel.replace(/\\/g, '/'))
  if (!rel || isAbsolute(clean) || clean.split(/[\\/]/).includes('..')) {
    throw new Error(`Unsafe path in manifest: ${rel}`)
  }
  const full = join(root, clean)
  if (!full.startsWith(normalize(root) + sep)) throw new Error(`Unsafe path in manifest: ${rel}`)
  return full
}

async function fetchManifest(url: string, signal?: AbortSignal): Promise<Manifest> {
  const res = await fetch(url, { headers: { 'Cache-Control': 'no-cache' }, signal })
  if (!res.ok) throw new Error(`Manifest download failed: HTTP ${res.status}`)
  const m = (await res.json()) as Manifest
  if (!Array.isArray(m.files)) throw new Error('Manifest is missing a "files" array')
  for (const f of m.files) {
    if (!/^[0-9a-f]{64}$/i.test(f.sha256)) throw new Error(`Bad sha256 in manifest for ${f.path}`)
  }
  return m
}

async function hashFile(path: string): Promise<string> {
  const h = createHash('sha256')
  await pipeline(createReadStream(path), h)
  return h.digest('hex')
}

async function loadState(root: string): Promise<LocalState> {
  try {
    return JSON.parse(await readFile(join(root, STATE_FILE), 'utf8'))
  } catch {
    return { files: {} }
  }
}

async function saveState(root: string, state: LocalState): Promise<void> {
  await mkdir(root, { recursive: true })
  const tmp = join(root, STATE_FILE + '.tmp')
  await writeFile(tmp, JSON.stringify(state))
  await rename(tmp, join(root, STATE_FILE))
}

/** Free bytes on the drive that holds `dir` (walks up to the nearest existing folder). */
export async function freeSpace(dir: string): Promise<number | undefined> {
  let d = dir
  while (!existsSync(d)) {
    const up = dirname(d)
    if (up === d) break
    d = up
  }
  try {
    const s = await statfs(d || parse(dir).root)
    return s.bavail * s.bsize
  } catch {
    return undefined
  }
}

/** Calls fn at most once per interval, but always lets `force` calls through. */
function throttle<T>(fn: (v: T) => void): (v: T, force?: boolean) => void {
  let last = 0
  return (v, force) => {
    const now = Date.now()
    if (force || now - last >= PROGRESS_INTERVAL_MS) {
      last = now
      fn(v)
    }
  }
}

async function runPool<T>(items: T[], n: number, fn: (item: T) => Promise<void>, signal?: AbortSignal): Promise<void> {
  let i = 0
  const worker = async (): Promise<void> => {
    while (i < items.length) {
      if (signal?.aborted) throw new CancelledError()
      await fn(items[i++])
    }
  }
  await Promise.all(Array.from({ length: Math.max(1, Math.min(n, items.length)) }, worker))
}

interface Plan {
  manifest: Manifest
  baseUrl: string
  toDownload: ManifestFile[]
  toDelete: string[]
  state: LocalState
}

async function buildPlan(root: string, manifestUrl: string, opts: PatchOptions, onProgress?: (p: PatchProgress) => void): Promise<Plan> {
  const manifest = await fetchManifest(manifestUrl, opts.signal)
  const baseUrl = manifest.baseUrl ?? new URL('files/', manifestUrl).toString()
  const state = await loadState(root)
  const toDownload: ManifestFile[] = []
  const emit = throttle((p: PatchProgress) => onProgress?.(p))
  const filesTotal = manifest.files.length
  let filesDone = 0
  let dirty = false

  await runPool(
    manifest.files,
    8,
    async (f) => {
      const full = safeJoin(root, f.path)
      emit({ phase: 'checking', currentFile: f.path, filesDone, filesTotal, bytesDone: 0, bytesTotal: 0 })
      filesDone++
      let st
      try {
        st = await stat(full)
      } catch {
        toDownload.push(f)
        return
      }
      if (st.size !== f.size) {
        toDownload.push(f)
        return
      }
      // Skip re-hashing when size and mtime match what we recorded last time.
      const cached = state.files[f.path]
      let hash: string
      if (!opts.verify && cached && cached.size === st.size && cached.mtimeMs === st.mtimeMs) {
        hash = cached.sha256
      } else {
        hash = await hashFile(full)
        state.files[f.path] = { size: st.size, mtimeMs: st.mtimeMs, sha256: hash }
        dirty = true
      }
      if (hash.toLowerCase() !== f.sha256.toLowerCase()) toDownload.push(f)
    },
    opts.signal
  )

  if (dirty) await saveState(root, state)
  const toDelete = (manifest.delete ?? []).filter((p) => existsSync(safeJoin(root, p)))
  return { manifest, baseUrl, toDownload, toDelete, state }
}

async function summarize(root: string, plan: Plan): Promise<UpdateCheck> {
  const gz = plan.manifest.compression === 'gzip'
  return {
    ok: true,
    version: plan.manifest.version,
    filesToDownload: plan.toDownload.length,
    bytesToDownload: plan.toDownload.reduce((n, f) => n + (gz ? (f.csize ?? f.size) : f.size), 0),
    bytesToWrite: plan.toDownload.reduce((n, f) => n + f.size, 0),
    filesToDelete: plan.toDelete.length,
    freeBytes: await freeSpace(root)
  }
}

export async function checkForUpdates(root: string, manifestUrl: string, opts: PatchOptions = {}, onProgress?: (p: PatchProgress) => void): Promise<UpdateCheck> {
  const plan = await buildPlan(root, manifestUrl, opts, onProgress)
  return summarize(root, plan)
}

function blobUrl(manifest: Manifest, baseUrl: string, f: ManifestFile): string {
  if (manifest.layout === 'sha256') {
    const h = f.sha256.toLowerCase()
    return new URL(`${h.slice(0, 2)}/${h}${manifest.compression === 'gzip' ? '.gz' : ''}`, baseUrl).toString()
  }
  return new URL(f.path.split('/').map(encodeURIComponent).join('/'), baseUrl).toString()
}

async function downloadFile(
  root: string,
  manifest: Manifest,
  baseUrl: string,
  f: ManifestFile,
  onBytes: (n: number) => void,
  signal?: AbortSignal
): Promise<StateEntry> {
  const dest = safeJoin(root, f.path)
  const part = dest + '.part'
  await mkdir(dirname(dest), { recursive: true })

  let lastErr: unknown
  for (let attempt = 1; attempt <= 3; attempt++) {
    let counted = 0
    try {
      const res = await fetch(blobUrl(manifest, baseUrl, f), { signal })
      if (!res.ok || !res.body) throw new Error(`Download failed for ${f.path}: HTTP ${res.status}`)

      const meter = new Transform({
        transform(chunk: Buffer, _enc, cb) {
          counted += chunk.length
          onBytes(chunk.length)
          cb(null, chunk)
        }
      })
      const hash = createHash('sha256')
      const hasher = new Transform({
        transform(chunk: Buffer, _enc, cb) {
          hash.update(chunk)
          cb(null, chunk)
        }
      })
      const body = Readable.fromWeb(res.body as WebReadableStream)
      const stages: (NodeJS.ReadableStream | NodeJS.WritableStream | Transform | Writable)[] = [body, meter]
      if (manifest.compression === 'gzip') stages.push(createGunzip())
      stages.push(hasher, createWriteStream(part))
      await (pipeline as (...s: unknown[]) => Promise<void>)(...stages, { signal })

      const digest = hash.digest('hex')
      if (digest !== f.sha256.toLowerCase()) throw new Error(`Checksum mismatch for ${f.path}`)
      await rm(dest, { force: true })
      await rename(part, dest)
      const st = await stat(dest)
      return { size: st.size, mtimeMs: st.mtimeMs, sha256: digest }
    } catch (err) {
      await rm(part, { force: true })
      onBytes(-counted) // roll back the progress of the failed attempt
      if (signal?.aborted) throw new CancelledError()
      lastErr = err
      if (attempt < 3) await new Promise((r) => setTimeout(r, 1000 * attempt))
    }
  }
  throw lastErr
}

export async function runUpdate(root: string, manifestUrl: string, onProgress: (p: PatchProgress) => void, opts: PatchOptions = {}): Promise<UpdateCheck> {
  const plan = await buildPlan(root, manifestUrl, opts, onProgress)
  const summary = await summarize(root, plan)

  if (summary.freeBytes !== undefined && summary.freeBytes < summary.bytesToWrite + DISK_MARGIN) {
    const gb = (n: number): string => (n / 1073741824).toFixed(1) + ' GB'
    throw new Error(`Not enough disk space: the update needs ${gb(summary.bytesToWrite + DISK_MARGIN)}, but only ${gb(summary.freeBytes)} is free.`)
  }

  const bytesTotal = summary.bytesToDownload
  const filesTotal = plan.toDownload.length
  let bytesDone = 0
  let filesDone = 0
  let current: string | undefined
  const emit = throttle(() => onProgress({ phase: 'downloading', currentFile: current, filesDone, filesTotal, bytesDone, bytesTotal }))

  for (const rel of plan.toDelete) {
    await rm(safeJoin(root, rel), { force: true, recursive: true })
    delete plan.state.files[rel]
  }

  // If one download fails for good, stop the others instead of letting them run on.
  const inner = new AbortController()
  const onOuterAbort = (): void => inner.abort()
  opts.signal?.addEventListener('abort', onOuterAbort)

  // Save progress periodically (serialized) so a crash or cancel doesn't force re-hashing everything.
  let saving = Promise.resolve()
  const save = (): Promise<void> => (saving = saving.then(() => saveState(root, plan.state)))
  let sinceSave = 0

  try {
    await runPool(
      plan.toDownload,
      opts.concurrency ?? 8,
      async (f) => {
        current = f.path
        try {
          plan.state.files[f.path] = await downloadFile(
            root,
            plan.manifest,
            plan.baseUrl,
            f,
            (n) => {
              bytesDone += n
              emit(undefined)
            },
            inner.signal
          )
        } catch (err) {
          inner.abort()
          throw err
        }
        filesDone++
        emit(undefined)
        if (++sinceSave >= 500) {
          sinceSave = 0
          await save()
        }
      },
      inner.signal
    )
  } catch (err) {
    // Report a user cancel as such, not as whatever error the aborted fetch raised.
    if (opts.signal?.aborted) throw new CancelledError()
    throw err
  } finally {
    opts.signal?.removeEventListener('abort', onOuterAbort)
    await save()
  }

  plan.state.version = plan.manifest.version
  await saveState(root, plan.state)
  onProgress({ phase: 'done', filesDone, filesTotal, bytesDone, bytesTotal })
  return { ...summary, filesToDownload: 0, bytesToDownload: 0, bytesToWrite: 0, filesToDelete: 0, freeBytes: await freeSpace(root) }
}
